00040     public function register()
00041     {
00042         // Params
00043         set_time_limit(0);
00044         clearstatcache();
00045 
00046         // Error log
00047         $this->initErrorHandling();
00048 
00049         // External classes
00050         require_once $this->path . '/classes/class.log.php';
00051         require_once $this->path . '/classes/class.util.php';
00052         require_once $this->path . '/classes/class.util.string.php';
00053         Log::init();
00054 
00055         // Autoloader
00056         require_once $this->path . '/classes/class.autoloader.php';
00057         $bearsamppAutoloader = new Autoloader();
00058         $bearsamppAutoloader->register();
00059 
00060         // Module loaders for async initialization
00061         require_once $this->path . '/classes/class.moduleloader.php';
00062         require_once $this->path . '/classes/class.cachemanager.php';
00063         require_once $this->path . '/classes/class.fibermoduleloader.php';
00064 
00065         // Initialize cache system (disk caching for warm starts)
00066         CacheManager::init(Path::getTmpPath() . '/cache');
00067 
00068         // Initialize fiber loader (true async for 8.1+)
00069         $useFibers = FiberModuleLoader::init();
00070 
00071         // Load critical modules synchronously (required for main functionality)
00072         self::loadCore();
00073         self::loadConfig();
00074         self::loadLang();
00075         self::loadOpenSsl();
00076         self::loadBins();
00077         Log::separator();
00078 
00079         // Load non-critical modules asynchronously (for UI/admin functions)
00080         // Uses Fibers if PHP 8.1+, fallback to deferred loading
00081         if ($useFibers) {
00082             self::loadToolsFiber();
00083             self::loadAppsFiber();
00084             self::loadRegistryFiber();
00085             self::loadHomepageFiber();
00086         } else {
00087             self::loadToolsAsync();
00088             self::loadAppsAsync();
00089             self::loadRegistryAsync();
00090             self::loadHomepageAsync();
00091         }
00092 
00093         self::loadWinbinder();
00094     }
