00383     public function errorHandler($errno, $errstr, $errfile, $errline)
00384     {
00385         if (!(error_reporting() & $errno)) {
00386             return;
00387         }
00388 
00389         $errfile = Path::formatUnixPath($errfile);
00390         $errfile = str_replace(Path::getRootPath(), '', $errfile);
00391 
00392         if (!defined('E_DEPRECATED')) {
00393             define('E_DEPRECATED', 8192);
00394         }
00395 
00396         $errNames = array(
00397             E_ERROR             => 'E_ERROR',
00398             E_WARNING           => 'E_WARNING',
00399             E_PARSE             => 'E_PARSE',
00400             E_NOTICE            => 'E_NOTICE',
00401             E_CORE_ERROR        => 'E_CORE_ERROR',
00402             E_CORE_WARNING      => 'E_CORE_WARNING',
00403             E_COMPILE_ERROR     => 'E_COMPILE_ERROR',
00404             E_COMPILE_WARNING   => 'E_COMPILE_WARNING',
00405             E_USER_ERROR        => 'E_USER_ERROR',
00406             E_USER_WARNING      => 'E_USER_WARNING',
00407             E_USER_NOTICE       => 'E_USER_NOTICE',
00408             E_RECOVERABLE_ERROR => 'E_RECOVERABLE_ERROR',
00409             E_DEPRECATED        => 'E_DEPRECATED',
00410         );
00411 
00412         $content = '[' . date('Y-m-d H:i:s', time()) . '] ';
00413         $content .= $errNames[$errno] . ' ';
00414         $content .= $errstr . ' in ' .  $errfile;
00415         $content .= ' on line ' . $errline . PHP_EOL;
00416         $content .= self::debugStringBacktrace() . PHP_EOL;
00417 
00418         file_put_contents(Path::getErrorLogFilePath(), $content, FILE_APPEND);
00419     }
00420 
00426     private static function debugStringBacktrace()
00427     {
00428         ob_start();
00429         debug_print_backtrace();
00430         $trace = ob_get_contents();
00431         ob_end_clean();
00432 
00433         $trace = preg_replace('/^#0\s+Root::debugStringBacktrace[^\n]*\n/', '', $trace, 1);
00434         $trace = preg_replace('/^#1\s+isRoot->errorHandler[^\n]*\n/', '', $trace, 1);
00435         $trace = preg_replace_callback('/^#(\d+)/m', 'debugStringPregReplace', $trace);
00436         return $trace;
00437     }
00438 }
